// =========================
// CONFIGURACIÓN
// =========================
const COORD_NODE = 'ADAPTADOR';          // nombre exacto del nodo que tiene lat/lon
const TIMEZONE = 'Europe/Madrid';        // hora local España
const MAX_AGE_MINUTES = 180;             // preferir estaciones con dato reciente (3h); si no hay, elige la más cercana igualmente
const DEBUG_TOP_N = 0;                   // pon 5 si quieres devolver top 5 cercanas para debug (0 = no)

// =========================
// 1) Coordenadas del lugar (Nominatim -> ADAPTADOR)
// =========================
const user = $(COORD_NODE).first().json;
const userLat = Number(user.lat);
const userLon = Number(user.lon);

if (!Number.isFinite(userLat) || !Number.isFinite(userLon)) {
  throw new Error(`No hay lat/lon válidos en el nodo "${COORD_NODE}".`);
}

// =========================
// 2) Leer datos de AEMET (AEMET2)
// =========================
const payload = items[0].json;

// AEMET2 en n8n a veces viene como { data: "....JSON...." }
let rows = [];
if (typeof payload?.data === 'string') {
  try {
    rows = JSON.parse(payload.data);
  } catch (e) {
    throw new Error('AEMET2 trae "data" como string, pero no es JSON válido.');
  }
} else if (Array.isArray(payload)) {
  rows = payload;
} else if (Array.isArray(payload?.data)) {
  rows = payload.data;
} else if (typeof payload === 'string') {
  rows = JSON.parse(payload);
} else {
  rows = payload;
}

if (!Array.isArray(rows) || rows.length === 0) {
  throw new Error('AEMET no devolvió datos (array vacío o formato inesperado).');
}

// =========================
// 3) Helpers: lat/lon, Haversine, timestamp robusto
// =========================
const toNumber = (v) => {
  if (v === null || v === undefined) return NaN;
  return Number(String(v).replace(',', '.'));
};

const toRad = (deg) => (deg * Math.PI) / 180;

const haversineKm = (lat1, lon1, lat2, lon2) => {
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
};

// AEMET a veces devuelve fint como "2026-02-28T07:00:00+0000" (sin dos puntos)
// Normalizamos a "+00:00" para que Date.parse sea fiable.
const normalizeOffset = (s) => {
  if (typeof s !== 'string') return s;
  return s.replace(/([+-]\d{2})(\d{2})$/, '$1:$2');
};

const parseFintToMs = (fint) => {
  if (!fint) return NaN;
  const norm = normalizeOffset(fint);
  const ms = Date.parse(norm);
  return Number.isFinite(ms) ? ms : NaN;
};

// ✅ Hora España (dependiendo de soporte ICU del sistema)
const formatMadridTime = (ms) => {
  try {
    const dtf = new Intl.DateTimeFormat('es-ES', {
      timeZone: TIMEZONE,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    });
    return dtf.format(new Date(ms));
  } catch {
    return null;
  }
};

// =========================
// 4) Agrupar por estación y guardar la observación más reciente por idema
// =========================
const stationMap = new Map();

for (const r of rows) {
  const id = r.idema;
  if (!id) continue;

  const lat = toNumber(r.lat);
  const lon = toNumber(r.lon);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

  const ms = parseFintToMs(r.fint);

  if (!stationMap.has(id)) {
    stationMap.set(id, {
      idema: id,
      lat,
      lon,
      ubi: r.ubi ?? null,
      latestRow: null,
      latestMs: -Infinity,
      fallbackRow: r,
    });
  }

  const entry = stationMap.get(id);

  if (!entry.ubi && r.ubi) entry.ubi = r.ubi;

  if (Number.isFinite(ms) && ms > entry.latestMs) {
    entry.latestMs = ms;
    entry.latestRow = r;
  } else if (!entry.fallbackRow) {
    entry.fallbackRow = r;
  }
}

if (stationMap.size === 0) {
  throw new Error('No hay estaciones válidas (faltan lat/lon/idema en los datos de AEMET).');
}

// =========================
// 5) Elegir estación: la más cercana, pero preferimos dato reciente
// =========================
const nowMs = Date.now();
const candidates = [];

for (const entry of stationMap.values()) {
  const d = haversineKm(userLat, userLon, entry.lat, entry.lon);
  const row = entry.latestRow ?? entry.fallbackRow;

  const ms = parseFintToMs(row?.fint);
  const ageMin = Number.isFinite(ms) ? (nowMs - ms) / 60000 : Infinity;

  candidates.push({
    idema: entry.idema,
    ubi: entry.ubi,
    distance_km: d,
    row,
    ms,
    ageMin,
  });
}

candidates.sort((a, b) => a.distance_km - b.distance_km);

let best = candidates.find(c => c.ageMin <= MAX_AGE_MINUTES) ?? candidates[0];

if (!best || !best.row) {
  throw new Error('No pude seleccionar una estación válida.');
}

// =========================
// 6) Salida estable + hora local Madrid
// =========================
const r = best.row;
const bestMs = parseFintToMs(r.fint);

const out = {
  idema: r.idema ?? best.idema ?? null,
  ubi: r.ubi ?? best.ubi ?? null,
  distance_km: Math.round(best.distance_km * 10) / 10,

  // timestamps
  timestamp: r.fint ?? null, // tal cual viene de AEMET (puede venir en UTC)
  timestamp_local: Number.isFinite(bestMs) ? formatMadridTime(bestMs) : null,
  age_minutes: Number.isFinite(best.ageMin) ? Math.round(best.ageMin) : null,

  // observación actual
  wind_speed: r.vv ?? null,
  wind_dir_deg: r.dv ?? null,
  temp_c: r.ta ?? null,
  humidity_pct: r.hr ?? null,
  gust_ms: r.vmax ?? null,
  precip_mm: r.prec ?? null,
  pressure_hpa: r.pres ?? null,
};

if (DEBUG_TOP_N > 0) {
  out.nearest = candidates.slice(0, DEBUG_TOP_N).map(c => ({
    idema: c.idema,
    ubi: c.ubi,
    distance_km: Math.round(c.distance_km * 10) / 10,
    fint: c.row?.fint ?? null,
    timestamp_local: Number.isFinite(parseFintToMs(c.row?.fint)) ? formatMadridTime(parseFintToMs(c.row?.fint)) : null,
    age_minutes: Number.isFinite(c.ageMin) ? Math.round(c.ageMin) : null,
  }));
}

return [{ json: out }];

// Nominatim normalmente devuelve un array con 1 resultado (limit=1)
const res = items[0].json;

const first = Array.isArray(res) ? res[0] : res;

if (!first || !first.lat || !first.lon) {
  throw new Error("Nominatim no devolvió lat/lon.");
}

return [{
  json: {
    lat: Number(first.lat),
    lon: Number(first.lon),
  }
}];

const j = items[0].json;

// Acepta location directamente
let location = j.location;

// (Opcional) compatibilidad por si llega con otros nombres
if (!location) location = j.ubicacion || j.ubicación || j.message || j.text || j.input;

if (!location || typeof location !== 'string') {
  throw new Error('No llegó un lugar válido. Se esperaba el campo "location".');
}

return [{ json: { location: location.trim() } }];
